"use client";

import { useId, useState } from "react";
import { planCardDefaults, type PlanCardSpecProps } from "../generated/plan-card.types";
import { ActionButton } from "../action-button/action-button";
import { Alert } from "../alert/alert";
import { Badge } from "../badge/badge";
import { Button } from "../button/button";
import { EmptyState } from "../empty-state/empty-state";
import { ErrorState } from "../error-state/error-state";
import { Skeleton } from "../skeleton/skeleton";
import { cx } from "../utils/cx";
import { formatDay, formatPrice } from "../utils/billing-format";
import { CheckIcon } from "../utils/icons";
import { StateBoundary } from "../utils/state-boundary";

export interface PlanCardProps extends PlanCardSpecProps {
  className?: string;
}

type Status = NonNullable<PlanCardSpecProps["status"]>;

const statusLook: Record<Status, { text: string; variant: "success" | "info" | "warning" | "neutral" }> = {
  active: { text: "Active", variant: "success" },
  trialing: { text: "Trial", variant: "info" },
  past_due: { text: "Past due", variant: "warning" },
  canceled: { text: "Canceled", variant: "neutral" },
};

/** The line about the date, worded for the status. */
function dateLine(status: Status, day: string): string {
  if (!day) return status === "past_due" ? "Payment failed" : "";
  switch (status) {
    case "trialing":
      return `Trial ends on ${day}`;
    case "past_due":
      return `Payment failed. Renewal was due on ${day}`;
    case "canceled":
      return `Ends on ${day}`;
    default:
      return `Renews on ${day}`;
  }
}

/**
 * The current plan with its status, renewal date, features and the actions to change or cancel it. Cancelling asks
 * first and says when access ends. It changes nothing itself. UI permission is not security: the server must check again.
 */
export function PlanCard({
  plan,
  status = planCardDefaults.status,
  periodEnd,
  usageHint,
  locale = planCardDefaults.locale,
  state = "ready",
  onRetry,
  onChangePlan,
  onCancel,
  onUpdatePayment,
  permissions,
  classNames,
  className,
}: PlanCardProps) {
  const nameId = useId();
  const [announcement, setAnnouncement] = useState("");
  const day = formatDay(periodEnd, locale);
  const current: typeof state = state === "ready" && !plan ? "empty" : state;
  const root = cx(
    "flex w-full flex-col gap-4 rounded-[var(--rd-radius-overlay)] border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-default)] p-5 [box-shadow:var(--rd-elevation-raised)]",
    classNames?.root,
    className,
  );
  const look = statusLook[status];

  return (
    <div role="group" aria-labelledby={plan ? nameId : undefined} aria-label={plan ? undefined : "Plan"} className={root}>
      <StateBoundary
        state={current}
        loading={
          <div className="flex flex-col gap-3">
            <Skeleton variant="text" width="40%" />
            <Skeleton variant="text" width="25%" />
            <Skeleton variant="text" lines={3} />
          </div>
        }
        empty={
          <EmptyState size="sm" title="You are not on a plan yet" description="Choose a plan to get started.">
            {onChangePlan && (
              <ActionButton permission={permissions?.changePlan} onAction={onChangePlan} className={classNames?.changeButton}>
                Choose a plan
              </ActionButton>
            )}
          </EmptyState>
        }
        error={
          <ErrorState
            variant="inline"
            title="Couldn't load your plan"
            description="Your plan is not affected. Try again in a moment."
            actions={
              onRetry && (
                <Button variant="secondary" onPress={onRetry}>
                  Try again
                </Button>
              )
            }
          />
        }
      >
        {plan && (
          <>
            <div className={cx("flex flex-wrap items-center justify-between gap-x-3 gap-y-2", classNames?.header)}>
              <h2 id={nameId} className={cx("text-lg font-semibold text-[var(--rd-color-text-default)]", classNames?.name)}>
                {plan.name}
              </h2>
              <Badge variant={look.variant} className={classNames?.status}>
                {look.text}
              </Badge>
            </div>

            {status === "past_due" && (
              <Alert variant="warning" title="Your last payment failed" className={classNames?.alert}>
                <span className="flex flex-wrap items-center justify-between gap-2">
                  <span>Update your payment method to keep your plan active.</span>
                  {onUpdatePayment && (
                    <ActionButton variant="secondary" size="sm" onAction={onUpdatePayment} className={classNames?.updateButton}>
                      Update payment method
                    </ActionButton>
                  )}
                </span>
              </Alert>
            )}

            <div className="flex flex-col gap-1">
              <p className={cx("text-[var(--rd-color-text-default)]", classNames?.price)}>
                <span className="text-2xl font-semibold tabular-nums">{formatPrice(plan.price, plan.currency, locale)}</span>
                <span className="text-sm text-[var(--rd-color-text-muted)]"> per {plan.interval}</span>
              </p>
              {dateLine(status, day) && <p className={cx("text-sm text-[var(--rd-color-text-muted)]", classNames?.renewal)}>{dateLine(status, day)}</p>}
              {plan.description && <p className="text-sm text-[var(--rd-color-text-muted)]">{plan.description}</p>}
            </div>

            {plan.features && plan.features.length > 0 && (
              <ul aria-label={`${plan.name} includes`} className={cx("flex flex-col gap-1.5", classNames?.features)}>
                {plan.features.map((feature) => (
                  <li key={feature} className={cx("flex items-start gap-2 text-sm text-[var(--rd-color-text-default)]", classNames?.feature)}>
                    <CheckIcon className="mt-0.5 size-4 shrink-0 text-[var(--rd-color-feedback-success)]" />
                    {feature}
                  </li>
                ))}
              </ul>
            )}

            {usageHint && <p className={cx("text-sm text-[var(--rd-color-text-muted)]", classNames?.usage)}>{usageHint}</p>}

            {(onChangePlan || (onCancel && status !== "canceled")) && (
              <div className={cx("flex flex-wrap items-center gap-2 border-t border-[var(--rd-color-border-default)] pt-4", classNames?.actions)}>
                {onChangePlan && (
                  <ActionButton permission={permissions?.changePlan} onAction={onChangePlan} className={classNames?.changeButton}>
                    {status === "canceled" ? "Choose a plan" : "Change plan"}
                  </ActionButton>
                )}
                {onCancel && status !== "canceled" && (
                  <ActionButton
                    variant="danger"
                    permission={permissions?.cancel}
                    onAction={onCancel}
                    onSuccess={() => setAnnouncement(day ? `Subscription canceled. You keep access until ${day}.` : "Subscription canceled.")}
                    confirm={{
                      title: "Cancel your subscription?",
                      description: day
                        ? `You keep access to ${plan.name} until ${day}. After that it is not renewed.`
                        : `You keep access to ${plan.name} until the end of the current period. After that it is not renewed.`,
                      confirmLabel: "Cancel subscription",
                      cancelLabel: "Keep my plan",
                    }}
                    className={classNames?.cancelButton}
                  >
                    Cancel subscription
                  </ActionButton>
                )}
              </div>
            )}
          </>
        )}
      </StateBoundary>
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

"use client";

import { useId, useState } from "react";
import { Radio, RadioGroup } from "react-aria-components";
import { ActionButton } from "../action-button/action-button";
import { Badge } from "../badge/badge";
import { Button } from "../button/button";
import { SegmentedControl, SegmentedControlItem } from "../segmented-control/segmented-control";
import { cx } from "../utils/cx";
import { formatPrice } from "../utils/billing-format";
import { CheckIcon } from "../utils/icons";
import { resolvePermission, type Permissions } from "../utils/permissions";

export type PlanInterval = "month" | "year";

export interface PlanOption {
  id: string;
  name: string;
  description?: string;
  /** The price of one interval, in whole units: 49 for $49 a month, 490 for $490 a year. */
  prices: { month: number; year: number };
  currency?: string;
  features?: string[];
  /** A short word on the card, e.g. "Most popular". */
  badge?: string;
}

export interface PlanPickerProps {
  plans: PlanOption[];
  /** The plan the workspace is on now. It is marked "Current plan". */
  currentPlanId?: string;
  /** The interval of the current plan; picking it again is not a change. */
  currentInterval?: PlanInterval;
  /** The chosen plan, when you control it. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (planId: string) => void;
  /** The shown interval, when you control it. */
  interval?: PlanInterval;
  defaultInterval?: PlanInterval;
  onIntervalChange?: (interval: PlanInterval) => void;
  /** A note beside Yearly, e.g. "2 months free". By default it says how much the cheapest saving is. */
  yearlyNote?: string;
  /** Switches to the chosen plan; yours, async. */
  onSelectPlan: (planId: string, interval: PlanInterval) => void | Promise<unknown>;
  /** The text of the button for the chosen plan. */
  selectLabel?: (plan: PlanOption) => string;
  /** Names the group for screen readers. */
  label?: string;
  permissions?: Permissions<"select">;
  locale?: string;
  className?: string;
  classNames?: Partial<Record<"root" | "interval" | "plans" | "plan" | "badge" | "features" | "actions" | "selectButton" | "hint", string>>;
}

/** The biggest percentage the yearly price saves over twelve months, or 0. */
function biggestSaving(plans: PlanOption[]): number {
  return Math.max(0, ...plans.map((p) => (p.prices.month > 0 ? Math.round((1 - p.prices.year / (p.prices.month * 12)) * 100) : 0)));
}

/**
 * Plans as a group of radio cards with a monthly or yearly toggle. Choosing a card changes nothing until the button
 * is pressed; then onSelectPlan runs. UI permission is not security: the server must check again.
 */
export function PlanPicker({
  plans,
  currentPlanId,
  currentInterval,
  value,
  defaultValue,
  onValueChange,
  interval,
  defaultInterval = "month",
  onIntervalChange,
  yearlyNote,
  onSelectPlan,
  selectLabel = (plan) => `Switch to ${plan.name}`,
  label = "Plans",
  permissions,
  locale = "en-US",
  className,
  classNames,
}: PlanPickerProps) {
  const [innerValue, setInnerValue] = useState(defaultValue ?? currentPlanId ?? plans[0]?.id ?? "");
  const [innerInterval, setInnerInterval] = useState<PlanInterval>(defaultInterval);
  const hintId = useId();
  const access = resolvePermission(permissions?.select);
  if (!access.isVisible) return null;

  const chosenId = value ?? innerValue;
  const shownInterval = interval ?? innerInterval;
  const chosen = plans.find((p) => p.id === chosenId);
  const saving = biggestSaving(plans);
  const note = yearlyNote ?? (saving > 0 ? `Save up to ${saving}%` : undefined);
  const isCurrent = chosen?.id === currentPlanId && (currentInterval === undefined || currentInterval === shownInterval);

  return (
    <div className={cx("flex w-full flex-col gap-4", classNames?.root, className)}>
      <div className={cx("flex flex-wrap items-center gap-3", classNames?.interval)}>
        <SegmentedControl
          label="Billing interval"
          selectedKey={shownInterval}
          onChange={(key) => {
            const next = key as PlanInterval;
            if (interval === undefined) setInnerInterval(next);
            onIntervalChange?.(next);
          }}
        >
          <SegmentedControlItem id="month">Monthly</SegmentedControlItem>
          <SegmentedControlItem id="year">Yearly</SegmentedControlItem>
        </SegmentedControl>
        {note && <span className="text-sm text-[var(--rd-color-text-muted)]">{note} with yearly billing</span>}
      </div>

      <RadioGroup
        aria-label={label}
        value={chosenId}
        onChange={(next) => {
          if (value === undefined) setInnerValue(next);
          onValueChange?.(next);
        }}
        className={cx("grid gap-3 [grid-template-columns:repeat(auto-fit,minmax(15rem,1fr))]", classNames?.plans)}
      >
        {plans.map((plan) => {
          const price = formatPrice(plan.prices[shownInterval], plan.currency, locale);
          const isCurrentPlan = plan.id === currentPlanId;
          return (
            <Radio
              key={plan.id}
              value={plan.id}
              aria-label={`${plan.name}, ${price} per ${shownInterval}${isCurrentPlan ? ", current plan" : ""}`}
              className={cx(
                "group flex cursor-pointer flex-col gap-3 rounded-[var(--rd-radius-overlay)] border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-default)] p-4 outline-none",
                "data-[hovered]:border-[var(--rd-color-border-strong)]",
                "data-[selected]:border-[var(--rd-color-action-primary)] data-[selected]:[box-shadow:0_0_0_1px_var(--rd-color-action-primary)]",
                "data-[focus-visible]:ring-2 data-[focus-visible]:ring-offset-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
                classNames?.plan,
              )}
            >
              <span className="flex flex-wrap items-center justify-between gap-2">
                <span className="text-base font-semibold text-[var(--rd-color-text-default)]">{plan.name}</span>
                <span className="flex flex-wrap items-center gap-1.5">
                  {isCurrentPlan && (
                    <Badge variant="success" size="sm">
                      Current plan
                    </Badge>
                  )}
                  {plan.badge && (
                    <Badge variant="info" size="sm" className={classNames?.badge}>
                      {plan.badge}
                    </Badge>
                  )}
                </span>
              </span>
              <span className="text-[var(--rd-color-text-default)]">
                <span className="text-2xl font-semibold tabular-nums">{price}</span>
                <span className="text-sm text-[var(--rd-color-text-muted)]"> per {shownInterval}</span>
              </span>
              {plan.description && <span className="text-sm text-[var(--rd-color-text-muted)]">{plan.description}</span>}
              {plan.features && plan.features.length > 0 && (
                <span className={cx("flex flex-col gap-1.5", classNames?.features)}>
                  {plan.features.map((feature) => (
                    <span key={feature} className="flex items-start gap-2 text-sm text-[var(--rd-color-text-default)]">
                      <CheckIcon className="mt-0.5 size-4 shrink-0 text-[var(--rd-color-feedback-success)]" />
                      {feature}
                    </span>
                  ))}
                </span>
              )}
            </Radio>
          );
        })}
      </RadioGroup>

      <div className={cx("flex flex-wrap items-center justify-end gap-3", classNames?.actions)}>
        {access.isDisabled && access.reason && (
          <p id={hintId} className={cx("me-auto text-sm text-[var(--rd-color-text-muted)]", classNames?.hint)}>
            {access.reason}
          </p>
        )}
        {isCurrent && !access.isDisabled && (
          <p id={hintId} className={cx("me-auto text-sm text-[var(--rd-color-text-muted)]", classNames?.hint)}>
            This is your current plan.
          </p>
        )}
        {chosen &&
          (access.isDisabled ? (
            <Button
              aria-disabled="true"
              aria-describedby={access.reason ? hintId : undefined}
              onPress={() => {}}
              className={cx("opacity-50 cursor-not-allowed", classNames?.selectButton)}
            >
              {selectLabel(chosen)}
            </Button>
          ) : isCurrent ? (
            <Button isDisabled aria-describedby={hintId} className={classNames?.selectButton}>
              {selectLabel(chosen)}
            </Button>
          ) : (
            <ActionButton onAction={() => onSelectPlan(chosen.id, shownInterval)} className={classNames?.selectButton}>
              {selectLabel(chosen)}
            </ActionButton>
          ))}
      </div>
    </div>
  );
}

// Generated by rdloom codegen from specs/plan-card.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const planCardStatusValues = ["active", "trialing", "past_due", "canceled"] as const;

/** The current subscription plan: name, price and interval, status with the right text, renewal or end date, feature list, a usage hint, and the actions Change plan and Cancel subscription (confirmed, with the end date). A past due plan shows an alert. PlanPicker, exported beside it, lets people choose another plan. Your callbacks do the work. UI permission is not security: the server must check again. */
export interface PlanCardSpecProps {
  /**
   * The plan: its name, the price per interval (in whole units, e.g. 49 for $49), an ISO currency code (default USD), an optional description and the features it includes.
   */
  plan?: { name: string; price: number; interval: "month" | "year"; currency?: string; description?: string; features?: string[] };
  /**
   * Where the subscription stands. Each status has its own badge text and date line: active "Renews on", trialing "Trial ends on", past due "Payment failed", canceled "Ends on".
   * @default "active"
   */
  status?: "active" | "trialing" | "past_due" | "canceled";
  /**
   * When the current period ends: the renewal date, the trial end or the end of access. An ISO date string or a Date.
   */
  periodEnd?: Date | string;
  /**
   * One line about use, e.g. "8 of 10 seats used". For a meter use UsageMeter beside the card.
   */
  usageHint?: string;
  /**
   * The locale for the price and the dates.
   * @default "en-US"
   */
  locale?: string;
  /**
   * The data state: loading shows a skeleton, empty says there is no plan yet and offers Choose a plan, error shows a message with Try again.
   */
  state?: import("../utils/state").DataState;
  /**
   * Adds a Try again button to the error state.
   */
  onRetry?: () => void;
  /**
   * Starts changing the plan; yours, async. Usually opens a PlanPicker.
   */
  onChangePlan?: () => void | Promise<unknown>;
  /**
   * Cancels the subscription after the person confirmed in the dialog, which states the end date; yours, async.
   */
  onCancel?: () => void | Promise<unknown>;
  /**
   * Adds an Update payment method button to the past due alert.
   */
  onUpdatePayment?: () => void | Promise<unknown>;
  /**
   * What the app allows: changePlan and cancel. Hidden renders nothing; disabled keeps the control reachable (aria-disabled) with the reason shown and read, and nothing runs. This only changes what people see: the server must check again.
   */
  permissions?: import("../utils/permissions").Permissions<"changePlan" | "cancel">;
  /**
   * Extra class names for single parts, so you can restyle one part without editing the file. Keys: root, header, name, status, price, renewal, features, feature, usage, alert, actions, changeButton, cancelButton, updateButton.
   */
  classNames?: Partial<Record<"root" | "header" | "name" | "status" | "price" | "renewal" | "features" | "feature" | "usage" | "alert" | "actions" | "changeButton" | "cancelButton" | "updateButton", string>>;
}

export const planCardDefaults = {
  status: "active",
  locale: "en-US",
} as const;

export const planCardMeta = {
  "name": "PlanCard",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;
